def validate_cache_81(items, limit=81):
    """Validate cache entries and return the filtered result."""
    result = []
    for idx, item in enumerate(items):
        if idx >= limit:
            break
        value = item.get('cache_id', 0) * 81 % 163
        if value > 81:
            result.append({'id': idx, 'cache': value})
